using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Diagnostics;using System.Windows.Forms;
namespace FleetLab {
 public sealed class CreditsPage:UserControl {
  internal readonly Button BackButton=new Button(),PauseButton=new Button(),RestartButton=new Button();internal readonly ClipStudy Movie;internal readonly CreditsCanvas Canvas=new CreditsCanvas();
  internal CreditsRoll Roll {get;private set;}internal bool HasOpened{get;private set;}internal bool Playing{get;private set;}internal int Stage{get;private set;}internal int Factor{get;private set;}
  internal Bitmap CurrentImage{get{return image;}}public event Action ReturnRequested;
  readonly string assets;readonly Timer timer=new Timer();readonly Stopwatch clock=Stopwatch.StartNew();readonly Label note=new Label();ClassicSpriteFont font;IndexedImage entry;Bitmap image,exit;long last,elapsed;bool disposed;readonly CreditsCatalog catalog;NativeRandom random;string problem="";
  public CreditsPage(string root):this(root,null){}internal CreditsPage(string root,IClipOutput backend){assets=root;Dock=DockStyle.Fill;BackColor=Color.FromArgb(10,22,34);ForeColor=Color.WhiteSmoke;Movie=backend==null?new ClipStudy(root):new ClipStudy(root,backend);catalog=CreditsCatalog.Load(root);Movie.ConfigureCredits(catalog);
   var header=new TableLayoutPanel{Dock=DockStyle.Top,Height=112,ColumnCount=1,RowCount=3,Padding=new Padding(10,4,10,2)};foreach(int h in new[]{28,40,38})header.RowStyles.Add(new RowStyle(SizeType.Absolute,h));header.Controls.Add(new Label{Text="Original Credits · P pauses · Space / Escape returns to title",Dock=DockStyle.Fill},0,0);note.Dock=DockStyle.Fill;header.Controls.Add(note,0,1);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};header.Controls.Add(buttons,0,2);Add(buttons,BackButton,"Back to title",delegate{Back();});Add(buttons,PauseButton,"Pause",delegate{if(Playing)Pause();else Resume();});Add(buttons,RestartButton,"Restart text",delegate{if(Roll!=null&&Stage==1){Roll.Reset();Render();}});Canvas.Owner=this;Canvas.Dock=DockStyle.Fill;Controls.Add(Canvas);Controls.Add(header);
   timer.Interval=16;timer.Tick+=delegate{long now=clock.ElapsedMilliseconds,dt=now-last;last=now;if(Visible)Advance(dt);};timer.Start();Sync();
  }
  static void Add(Control p,Button b,string text,EventHandler action){b.Text=text;b.AutoSize=true;b.Height=32;b.FlatStyle=FlatStyle.Flat;b.BackColor=Color.FromArgb(31,56,75);b.ForeColor=Color.WhiteSmoke;b.Click+=action;p.Controls.Add(b);}
  internal void Begin(IndexedImage previous,bool high,uint? seed=null){if(disposed)return;Reset();CreditsProgram.Read(File.ReadAllBytes(Path.Combine(Path.GetDirectoryName(assets),"Programs","Credits.seqbin")));var text=new CreditsText(File.ReadAllBytes(Path.Combine(assets,"Graphics","CREDITS.TXT")));font=new ClassicSpriteFont(Path.Combine(assets,"Graphics"),ClassicPalette.Gameplay(File.ReadAllBytes(Path.Combine(assets,"Graphics","ISLAND.COL"))),true);Roll=new CreditsRoll(text);entry=previous;Movie.SetDetail(high);random=new NativeRandom(seed??unchecked((uint)Environment.TickCount));Stage=0;Factor=64;elapsed=0;HasOpened=Playing=true;last=clock.ElapsedMilliseconds;Render();Sync();Canvas.Focus();}
  internal void Advance(long ms){if(disposed||!HasOpened||!Playing)return;if(ms<0)throw new ArgumentOutOfRangeException("ms");ms=Math.Min(ms,500);if(Stage==1){long before=Roll.Ticks;bool changed=Roll.Advance(ms);if(changed){long ticks=Roll.Ticks-before;for(long i=0;i<ticks;i++){if(Movie.Timeline==null||Movie.Timeline.Completed){if(!NextMovie())break;}else Movie.AdvanceCredits(50);}Render();}Sync();return;}elapsed+=ms;while(elapsed>=40&&HasOpened&&Stage!=1){elapsed-=40;if(Factor==0){if(Stage==0){Stage=1;entry=null;elapsed=0;}else{Complete();return;}}else Factor-=4;}Render();Sync();}
  bool NextMovie(){string name=catalog.Choose(random);if(!Movie.LoadBattle(name)){problem=Movie.Problem;Movie.UnloadBattle();return false;}problem="";Movie.ResumePlayback();return true;}
  internal void FinishEntry(){if(disposed||!HasOpened)return;Stage=1;Factor=64;entry=null;elapsed=0;Render();Sync();}
  public void Pause(){if(disposed)return;Playing=false;Movie.Pause();Sync();}
  internal void Resume(){if(disposed||!HasOpened)return;Playing=true;last=clock.ElapsedMilliseconds;if(Stage==1&&Movie.Timeline!=null&&!Movie.Timeline.Completed)Movie.ResumePlayback();Sync();Canvas.Focus();}
  internal void Back(){if(disposed||!HasOpened||Stage==2)return;Movie.Pause();if(image!=null)exit=new Bitmap(image);Stage=2;Factor=64;elapsed=0;Playing=true;last=clock.ElapsedMilliseconds;Sync();}
  void Complete(){Playing=false;HasOpened=false;Movie.UnloadBattle();if(ReturnRequested!=null)ReturnRequested();}
  internal bool Key(Keys key){if(!HasOpened)return false;if(key==Keys.Escape||key==Keys.Space){Back();return true;}if(key==Keys.P){if(Playing)Pause();else Resume();return true;}return false;}
  public void SetSound(bool enabled){if(!disposed)Movie.SetSound(enabled);}public void SetLevel(int level){if(!disposed)Movie.SetLevel(level);}
  void Render(){if(disposed||!HasOpened||font==null)return;Bitmap next=new Bitmap(640,480);using(Graphics g=Graphics.FromImage(next)){g.Clear(Color.Black);g.InterpolationMode=InterpolationMode.NearestNeighbor;g.PixelOffsetMode=PixelOffsetMode.Half;if(Stage==0&&entry!=null){using(var card=new IndexedImage{Width=entry.Width,Height=entry.Height,Pixels=entry.Pixels,Palette=ClassicPalette.FadeDisplay(entry.Palette,Factor)}.Bitmap())g.DrawImageUnscaled(card,0,0);}else if(Stage==2&&exit!=null){float f=Factor/64f;using(var a=new ImageAttributes()){a.SetColorMatrix(new ColorMatrix(new float[][]{new[]{f,0f,0f,0f,0f},new[]{0f,f,0f,0f,0f},new[]{0f,0f,f,0f,0f},new[]{0f,0f,0f,1f,0f},new[]{0f,0f,0f,0f,1f}}));g.DrawImage(exit,new Rectangle(0,0,640,480),0,0,640,480,GraphicsUnit.Pixel,a);}}else if(Stage==1){if(Roll.Ticks>0&&Movie.CurrentImage!=null)g.DrawImage(Movie.CurrentImage,new Rectangle(0,0,640,480));if(Roll.Ticks>0)foreach(var line in Roll.Commands(font))font.Draw(g,line,4);}}
   Bitmap previous=image;image=next;Canvas.Invalidate();if(previous!=null)previous.Dispose();
  }
  void Sync(){if(disposed)return;PauseButton.Enabled=HasOpened;PauseButton.Text=Playing?"Pause":"Resume";RestartButton.Enabled=HasOpened&&Stage==1;BackButton.Enabled=HasOpened&&Stage!=2;if(problem!=""||Movie.Problem!="")note.Text=(problem!=""?problem:Movie.Problem)+" · Text continues.";else note.Text=Stage==1?"Credits · 137 original movie backgrounds · "+(Playing?"Playing":"Paused"):"Credits transition · "+(Playing?"Playing":"Paused");}
  public void Reset(){if(disposed)return;HasOpened=Playing=false;problem="";Roll=null;random=null;entry=null;Movie.UnloadBattle();if(font!=null)font.Dispose();font=null;if(image!=null)image.Dispose();image=null;if(exit!=null)exit.Dispose();exit=null;Stage=0;Canvas.Invalidate();Sync();}
  protected override void Dispose(bool disposing){if(disposing&&!disposed){Reset();disposed=true;timer.Stop();timer.Dispose();Movie.Dispose();Canvas.Owner=null;}base.Dispose(disposing);}
  internal sealed class CreditsCanvas:Control{internal CreditsPage Owner;public CreditsCanvas(){DoubleBuffered=true;ResizeRedraw=true;TabStop=true;BackColor=Color.Black;}protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);Focus();if(e.Button==MouseButtons.Left&&Owner!=null)Owner.Back();}protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Owner==null||Owner.image==null)return;float s=Math.Min(Width/640f,Height/480f);e.Graphics.InterpolationMode=InterpolationMode.NearestNeighbor;e.Graphics.PixelOffsetMode=PixelOffsetMode.Half;e.Graphics.DrawImage(Owner.image,new RectangleF((Width-640*s)/2,(Height-480*s)/2,640*s,480*s));}}
 }
}
